// Quarterly re-engagement: emails (within CASL 6-month window) and call tasks (older, or top deals).
const RAF = 'rlakhani@anagomb.ca', USER = 32883646;
const EMAIL_CAP = 15, CALL_CAP = 3, QUARTER_CALLS = 25, TOP = 10;
let scheduled = false;
try { scheduled = $('Every Tue-Thu 9:30').isExecuted; } catch (e) {}
const test = !scheduled;
const now = DateTime.now().setZone('America/Winnipeg');
const today = now.toISODate();
const qn = Math.ceil(now.month / 3);
const quarter = now.year + 'Q' + qn;
// quarterly campaign starts on the 2nd Tuesday of the quarter's first month
const m1 = now.set({ month: (qn - 1) * 3 + 1, day: 1 }).startOf('day');
const start = m1.plus({ days: ((2 - m1.weekday + 7) % 7) + 7 });
const START = '2027-01-01'; // nothing goes out before this date
const campaignOn = now >= start;
const lc = s => String(s || '').toLowerCase().trim();
const optout = new Set($('Get opt-outs').all().map(i => lc(i.json.email)).filter(Boolean));
const sentRows = $('Get sent log').all().map(i => i.json).filter(r => r.send_key);
const sent = new Set(sentRows.map(r => r.send_key));
const recentEmailed = new Set(sentRows.filter(r => !/^(call|d97):/.test(r.send_key) && now.diff(DateTime.fromISO(String(r.createdAt)), 'days').days < 60).map(r => r.send_key.split(':').pop()));
const replied = new Set($('Get replies').all().map(i => lc(i.json.email)).filter(Boolean));
const lost = $('Get lost deals').first().json.data || [];
const open = $('Get open deals').first().json.data || [];
const openPeople = new Set(open.map(d => d.person_id && d.person_id.value).filter(Boolean));
const openOrgs = new Set(open.map(d => d.org_id && d.org_id.value).filter(Boolean));
const dt = s => DateTime.fromISO(String(s).replace(' ', 'T'), { zone: 'utc' });

const F = 'font-family:Tahoma,Arial,Helvetica,sans-serif;font-size:10pt;color:#000';
const esc = s => String(s || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const p = t => '<p style="' + F + ';margin:0 0 12px 0">' + t + '</p>';
// Letsignit signature copied with its marker, so Letsignit does not add a second one.
const sig = '<div style="' + F + ';margin-top:16px">Kind Regards,</div>'
  + '<p style="margin:0.1pt;text-align:left"></p><p style="margin:0cm;font-size:15px;font-family:&quot;Calibri&quot;,sans-serif">Raf Lakhani <br />Brand Manager | Anago of Manitoba<br />238 St Mary’s Road | Winnipeg, MB R2H 1J3<br />t+ 204.594.4666 |Direct+ 204.809.4347 | <a href="mailto:rlakhani@anagomb.ca">rlakhani@anagomb.ca</a></p><p style="margin:0cm;font-size:15px;font-family:&quot;Calibri&quot;,sans-serif"><a href="http://www.anagomb.ca/">www.AnagoMB.ca</a></p><p></p><table><tbody><tr><td><div id="LSI_marker" style="font-size:0px"> </div></td></tr></tbody></table>';
const OFFER = 'I can do a free 20-minute walkthrough and send you an updated quote within a couple of days. Just reply with a time that suits you, or call me directly at 204-809-4347.';
const SEASON = {
  1: { subj: co => 'Winter floors at ' + (co || 'your building'), hook: 'This time of year, salt and slush get tracked in every day, and by February it shows on the floors and carpets. If it helps, I can include entrance matting and salt removal in the quote.' },
  2: { subj: co => 'Spring cleaning at ' + (co || 'your building'), hook: 'Spring is when most buildings catch up on what winter left behind: salt-stained floors, carpets, windows and vents. If a full contract is not the right step, I can also quote a one-time spring deep clean.' },
  3: { subj: co => 'Summer floor work at ' + (co || 'your building'), hook: 'Summer is the quiet window for floor work, like stripping and waxing or carpet extraction, before everyone is back in September. I can quote that as a one-time job, with no ongoing contract.' },
  4: { subj: co => 'Getting ' + (co || 'your building') + ' ready for winter', hook: 'Before winter hits, it is worth having entrance matting and a salt plan in place, and with flu season coming, regular disinfecting of high-touch areas matters more. I can include both in an updated quote.' },
};
const WENT = /another provider|Other Service/i, STAYED = /current provider|Same Service|In House/i;
function middle(r) {
  if (WENT.test(r)) return 'You went with another provider at the time, and I hope it is working well. If anything has slipped, like missed areas, frequent staff changes or slow responses, that is usually when businesses give us a second look.';
  if (STAYED.test(r)) return 'You decided to stay with your current provider at the time, and I hope it is working well. If anything has slipped, like missed areas, frequent staff changes or slow responses, that is usually when businesses give us a second look.';
  if (/Price/i.test(r)) return 'The price did not fit at the time. Budgets change, and so can the scope: we can adjust the frequency or focus on the high-traffic areas so the numbers work. I would be glad to rework the proposal around a budget you set.';
  return 'The timing was not right then, and that is completely fine. If anything has changed, like a contract coming up for renewal, a new space, or a cleaner who is not meeting expectations, I would be glad to help.';
}
function build(c, kind, q) {
  const d = c.d;
  const what = c.company ? esc(c.company) + (c.street ? ' at ' + c.street : '') : (c.street ? 'your space at ' + c.street : 'your space');
  const footer = '<p style="font-family:Tahoma,Arial,Helvetica,sans-serif;font-size:8pt;color:#808080;margin:12px 0 0 0">You are receiving this because you contacted Anago of Manitoba about cleaning' + (c.company ? ' for ' + esc(c.company) : '') + '. Reply “unsubscribe” and I will not email you again.</p>';
  let subject, body;
  if (kind === 'd90') {
    if (WENT.test(c.r)) {
      subject = 'How is the new cleaning team working out?';
      body = p('It has been about three months since you went with another provider for ' + what + '. That is usually when you find out whether a new crew is working out: the first few weeks are always good, and the details start to slip after that.');
    } else {
      subject = 'How is the cleaning going' + (c.company ? ' at ' + c.company : '') + '?';
      body = p('It has been about three months since you decided to stay with your current provider for ' + what + '. I hope it has been going well. If the issues that had you looking around have come back, that is usually the sign it will not fix itself.');
    }
    body += p('If everything is on track, great, no need to reply. If not, like missed areas, new faces every week or slow responses when you call, I would be glad to do a free 20-minute walkthrough and send you a quote within a couple of days. Just reply, or call me directly at 204-809-4347.');
  } else {
    const s = SEASON[q];
    const opener = (d['1a6bd14374c1ccde3e2bea35879a917c6a9d8c11'] ? 'In ' + c.year + ' we put together a cleaning proposal for ' : 'In ' + c.year + ' we spoke about cleaning for ') + what + '.';
    subject = s.subj(c.company);
    body = p(opener + ' ' + middle(c.r)) + p(s.hook) + p(OFFER);
  }
  const html = p('Hi ' + esc(c.first) + ',') + body + sig + footer;
  return { kind: 'email', live: !test, to: test ? RAF : c.email, subject, html, deal_id: d.id };
}
function callTask(c, key, subject, note) {
  return { kind: 'task', live: true, key, deal_id: c.d.id, activity: { subject, type: 'call', done: 0, user_id: USER, deal_id: c.d.id, person_id: c.personId || undefined, due_date: today, note } };
}

// Build the eligible list (one per email address, newest first).
const all = [];
const seen = new Set();
const sorted = lost.slice().sort((a, b) => String(b.lost_time || '').localeCompare(String(a.lost_time || '')));
for (const d of sorted) {
  const person = d.person_id || {};
  const em = person.email || [];
  const email = lc((em.find(e => e.primary) || em[0] || {}).value);
  if (!email || !/@/.test(email) || optout.has(email) || seen.has(email)) continue;
  const r = d.lost_reason || '';
  if (/Not Pursuing|Bad Data|Do Not Call|Franchise/i.test(r)) continue;
  if (openPeople.has(person.value) || (d.org_id && openOrgs.has(d.org_id.value))) continue;
  // Deals closed in bulk as "went quiet" carry the cleanup date, so use the date the lead came in.
  const ref = dt(/No response|went quiet/i.test(r) ? d.add_time : (d.lost_time || d.update_time));
  const age = now.diff(ref, 'days').days;
  const lostAge = now.diff(dt(d.lost_time || d.update_time), 'days').days;
  if (age > 3 * 365) continue;
  seen.add(email);
  const street = String((d.org_id && d.org_id.address) || '').split(',')[0].trim().replace(/\.+$/, '');
  let company = String(d.org_name || '').replace(/\s+c\/o\b.*$/i, '').replace(/,?\s+(Ltd|Inc|Corp|Corporation|Limited|Incorporated)\.?$/i, '').replace(/,\s*$/, '').trim();
  if (/^\d/.test(company) || lc(company) === lc(street)) company = ''; // org named after its address
  all.push({ d, r, email, age, lostAge, personId: person.value, value: Number(d.value) || 0,
    first: String(person.name || '').trim().split(/\s+/)[0] || 'there', company,
    street: esc(street), year: ref.toFormat('yyyy') });
}

const out = [];
if (test) {
  // Samples for Raf: one seasonal email per quarter, plus the 90-day email.
  const em = all.filter(c => c.age >= 60 && c.age < 183);
  for (let q = 1; q <= 4 && q <= em.length; q++) out.push({ json: (m => Object.assign(m, { subject: '[TEST Q' + q + ' to ' + em[q - 1].email + '] ' + m.subject }))(build(em[q - 1], 'q', q)) });
  const sw = all.find(c => WENT.test(c.r)); if (sw) out.push({ json: (m => Object.assign(m, { subject: '[TEST 90-day to ' + sw.email + '] ' + m.subject }))(build(sw, 'd90')) });
  const st = all.find(c => STAYED.test(c.r)); if (st) out.push({ json: (m => Object.assign(m, { subject: '[TEST 90-day to ' + st.email + '] ' + m.subject }))(build(st, 'd90')) });
  return out;
}

if (today < START) return [];
let emails = 0, calls = 0;
const SWITCH = c => WENT.test(c.r) || STAYED.test(c.r);
// 1. 90 days after losing to (or staying with) another provider: email, then a call task a week later.
for (const c of all) {
  if (!SWITCH(c)) continue;
  const k90 = 'd90:' + c.d.id + ':' + c.email;
  if (c.lostAge >= 90 && c.lostAge < 97 && !sent.has(k90) && emails < EMAIL_CAP) {
    out.push({ json: Object.assign(build(c, 'd90'), { key: k90 }) }); emails++; recentEmailed.add(c.email);
  }
  const k97 = 'd97:' + c.d.id;
  if (c.lostAge >= 97 && c.lostAge < 125 && sent.has(k90) && !sent.has(k97) && !replied.has(c.email)) {
    out.push({ json: callTask(c, k97, 'Call ' + c.first + (c.company ? ' at ' + c.company : '') + ': 90-day check-in after switching cleaners', 'We emailed them at day 90 (no reply yet). Ask how the current cleaner is doing. Lost reason: ' + c.r + '.') });
  }
}
// 2. Quarterly: top deals by value and contacts older than 6 months get a call task, the rest get the email.
if (campaignOn) {
  const qStart = m1.toUTC().toISO();
  const callsThisQuarter = sentRows.filter(r => /^call:/.test(r.send_key) && String(r.createdAt) >= qStart).length;
  const pool = all.filter(c => c.age >= 60);
  const top = new Set(pool.filter(c => c.value > 0).sort((a, b) => b.value - a.value).slice(0, TOP).map(c => c.d.id));
  const ordered = pool.slice().sort((a, b) => (top.has(b.d.id) - top.has(a.d.id)) || (a.age - b.age));
  for (const c of ordered) {
    // top deals: a call every quarter; older contacts: a call once a year
    const kq = quarter + ':' + c.email, kc = 'call:' + (top.has(c.d.id) ? quarter : now.year) + ':' + c.email;
    if (sent.has(kq) || sent.has(kc) || recentEmailed.has(c.email)) continue;
    if (top.has(c.d.id) || c.age >= 183) {
      if (calls >= CALL_CAP || callsThisQuarter + calls >= QUARTER_CALLS) continue;
      out.push({ json: callTask(c, kc, 'Quarterly call: ' + c.first + (c.company ? ' at ' + c.company : ''), (top.has(c.d.id) ? 'Top lost deal by value ($' + Math.round(c.value).toLocaleString() + '/yr). ' : '') + 'Lost reason: ' + c.r + ' (' + c.year + '). Talking point this quarter: ' + SEASON[qn].hook) });
      calls++;
    } else {
      if (emails >= EMAIL_CAP) continue;
      out.push({ json: Object.assign(build(c, 'q', qn), { key: kq }) }); emails++;
    }
  }
}
return out;

